def solve(g):
    g=[row[:] for row in g]
    cnt=Counter(v for row in g for v in row)
    for r in range(H):
        for c in range(W):
            v=g[r][c]
            nb=[g[r+dr][c+dc] for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)] if 0<=r+dr<H and 0<=c+dc<W]
            if nb:
                m=Counter(nb); mx=max(m.values())
                if v!=mx or len([k for k in m if m[k]==mx])>1:
                    cand=[k for k in m if m[k]==mx]
                    pick=min(cand,key=lambda k:cnt[k])
                    g[r][c]=pick
    return g
